use std::collections::HashMap;
use std::hash::Hash;

pub struct HopscotchMap<K, V> {
    entries: HashMap<K, V>,
}

impl<K, V> HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    pub fn new() -> Self {
        Self {
            entries: HashMap::new(),
        }
    }

    pub fn insert(&mut self, entry: (K, V)) -> Option<V> {
        self.entries.insert(entry.0, entry.1)
    }

    pub fn equal_range<'a>(&'a self, key: &K) -> EqualRange<'a, K, V> {
        EqualRange {
            entry: self.entries.get_key_value(key),
        }
    }
}

impl<K, V> Default for HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    fn default() -> Self {
        Self::new()
    }
}

pub struct EqualRange<'a, K, V> {
    entry: Option<(&'a K, &'a V)>,
}

impl<'a, K, V> Iterator for EqualRange<'a, K, V> {
    type Item = (&'a K, &'a V);

    fn next(&mut self) -> Option<Self::Item> {
        self.entry.take()
    }
}

#[cfg(test)]
mod tests {
    use super::HopscotchMap;

    #[test]
    fn equal_range_returns_one_for_existing_key() {
        let mut map = HopscotchMap::new();
        map.insert((3, 36));
        assert_eq!(map.equal_range(&3).count(), 1);
    }

    #[test]
    fn equal_range_returns_zero_for_missing_key() {
        let mut map = HopscotchMap::new();
        map.insert((3, 36));
        assert_eq!(map.equal_range(&4).count(), 0);
    }
}

